fn main() {
    let args: Vec<String> = std::env::args().collect();

    // Parse CLI arguments
    match args.get(1).map(|s| s.as_str()) {
        Some("--compile-aot") => {
            // Phase 10: Self-Compilation Verification
            compile_aot_mode(&args[2..]);
        }
        Some("--bench") => {
            run_benchmarks();
        }
        Some("--test") => {
            run_integration_tests();
        }
        Some(arg) if arg.ends_with(".fl") => {
            execute_file(arg);
        }
        Some("--help") | Some("-h") => {
            print_help();
        }
        _ => {
            // Default: run Challenge 14 validator + REPL
            run_default_mode();
        }
    }
}

