                println!("  {:3} | {}", i + 1, line);
            }

            if lines.len() > 10 {
                println!("  ... ({} more lines)", lines.len() - 10);
            }

            println!("\n✅ File loaded successfully");
        }
        Err(e) => {
            println!("❌ Error: Failed to read file '{}': {}", filename, e);
        }
    }
}

fn print_help() {
    println!("╔════════════════════════════════════════════════════════════╗");
    println!("║            FreeLang Compiler - Help                       ║");
    println!("╚════════════════════════════════════════════════════════════╝\n");

    println!("Usage: freelang [OPTION] [FILE]\n");

    println!("Options:");
    println!("  --bench           Run all benchmarks");
    println!("  --test            Run integration tests");
    println!("  --help, -h        Show this help message");
    println!("  <file.fl>         Execute a FreeLang file");
    println!("  (none)            Interactive REPL + Challenge 14 validator\n");

    println!("Examples:");
    println!("  freelang                  # Run Challenge 14 validator + REPL");
    println!("  freelang --bench          # Run benchmarks");
    println!("  freelang --test           # Run integration tests");
    println!("  freelang program.fl       # Execute program.fl\n");
}

fn interactive_mode() {
    let mut vm = VM::new();

    println!("\n╭─ Interactive FreeLang Console ────────────────────────╮");
    println!("│ Type commands: set <var> <value>, get <var>, test  │");
    println!("│ Type 'exit' to quit                                │");
    println!("╰───────────────────────────────────────────────────────╯\n");

    loop {
        print!("fl> ");
        io::stdout().flush().unwrap();

        let mut input = String::new();
        io::stdin().read_line(&mut input).unwrap();

        let input = input.trim();
        if input == "exit" {
            println!("Goodbye!");
            break;
        }

        let parts: Vec<&str> = input.split_whitespace().collect();
        match parts.as_slice() {
            ["set", var, value] => {
                if let Ok(n) = value.parse::<i64>() {
                    vm.set_variable(var.to_string(), Value::Integer(n));
                    println!("Set {} = {}", var, n);
                } else {
                    vm.set_variable(var.to_string(), Value::String(value.to_string()));
                    println!("Set {} = \"{}\"", var, value);
                }
            }
            ["get", var] => {
                if let Some(val) = vm.get_variable(var) {
                    println!("{} = {}", var, val.to_string());
                } else {
                    println!("Variable {} not found", var);
                }
            }
            ["test"] => {
                let mut validator = Challenge14Validator::new();
                validator.run_all_tests();
                validator.validate_all_rules();
            }
            ["help"] => {
                println!("Commands:");
                println!("  set <var> <value>  - Set variable");
                println!("  get <var>          - Get variable");
                println!("  test               - Run tests");
                println!("  exit               - Exit");
            }
            _ => println!("Unknown command. Type 'help' for usage."),
        }
    }
}

