    match lexer.tokenize() {
        Ok(tokens) => {
            total_tokens = tokens.len();

            // Collect statistics
            for token in &tokens {
                let key = format!("{:?}", std::mem::discriminant(token));
                *token_types.entry(key).or_insert(0) += 1;
