// FreeLang Compiler & VM
// Challenge 14 코드 실행 엔진
// 2026-03-05, Kim

use std::collections::HashMap;
use std::io::{self, Write};
use std::fs;
use std::path::Path;

// ============================================================================
// Lexer - 토큰화
// ============================================================================

#[derive(Debug, Clone, PartialEq)]
enum Token {
    // Keywords
    Fn,
    Pub,
    Module,
    Use,
    Type,
    Struct,
    If,
    Else,
    For,
    While,
    Return,
    Let,
    Mut,
    True,
    False,

    // Identifiers & Literals
    Identifier(String),
    Number(i64),
    String(String),

    // Operators
    Plus,
    Minus,
    Star,
    Slash,
    Percent,
    Equal,
    EqualEqual,
    NotEqual,
    Less,
    Greater,
    LessEqual,
    GreaterEqual,
    And,
    Or,
    Not,
    Xor,
    Arrow,

    // Delimiters
    LeftParen,
    RightParen,
    LeftBrace,
    RightBrace,
    LeftBracket,
    RightBracket,
    Comma,
    Dot,
    Colon,
    Semicolon,
    Pipe,

    // Special
    Eof,
}

struct Lexer {
    input: Vec<char>,
    pos: usize,
}

impl Lexer {
    fn new(input: &str) -> Self {
        Lexer {
            input: input.chars().collect(),
            pos: 0,
        }
    }

    fn current_char(&self) -> Option<char> {
        if self.pos < self.input.len() {
            Some(self.input[self.pos])
        } else {
            None
        }
    }

    fn peek_char(&self) -> Option<char> {
        if self.pos + 1 < self.input.len() {
            Some(self.input[self.pos + 1])
        } else {
            None
        }
    }

    fn advance(&mut self) {
        self.pos += 1;
    }

    fn skip_whitespace(&mut self) {
        while let Some(ch) = self.current_char() {
            if ch.is_whitespace() {
                self.advance();
            } else {
                break;
            }
        }
    }

    fn read_identifier(&mut self) -> String {
        let mut result = String::new();
        while let Some(ch) = self.current_char() {
            if ch.is_alphanumeric() || ch == '_' {
                result.push(ch);
                self.advance();
            } else {
                break;
            }
        }
        result
    }

    fn read_number(&mut self) -> i64 {
        let mut result = 0i64;
        while let Some(ch) = self.current_char() {
            if ch.is_digit(10) {
                result = result * 10 + (ch as i64 - '0' as i64);
                self.advance();
            } else {
                break;
            }
        }
        result
    }

    fn next_token(&mut self) -> Token {
        self.skip_whitespace();

        match self.current_char() {
            None => Token::Eof,
            Some(ch) => {
                match ch {
                    '(' => {
                        self.advance();
                        Token::LeftParen
                    }
                    ')' => {
                        self.advance();
                        Token::RightParen
                    }
                    '{' => {
                        self.advance();
                        Token::LeftBrace
                    }
                    '}' => {
                        self.advance();
                        Token::RightBrace
                    }
                    '[' => {
                        self.advance();
                        Token::LeftBracket
                    }
                    ']' => {
                        self.advance();
                        Token::RightBracket
                    }
                    ',' => {
                        self.advance();
                        Token::Comma
                    }
                    '.' => {
                        self.advance();
                        Token::Dot
                    }
                    ':' => {
                        self.advance();
                        Token::Colon
                    }
                    ';' => {
                        self.advance();
                        Token::Semicolon
                    }
                    '|' => {
                        self.advance();
                        Token::Pipe
                    }
                    '+' => {
                        self.advance();
                        Token::Plus
                    }
                    '-' => {
                        self.advance();
                        if self.current_char() == Some('>') {
                            self.advance();
                            Token::Arrow
                        } else {
                            Token::Minus
                        }
                    }
                    '*' => {
                        self.advance();
                        Token::Star
                    }
                    '/' => {
                        self.advance();
                        Token::Slash
                    }
                    '%' => {
                        self.advance();
                        Token::Percent
                    }
                    '=' => {
                        self.advance();
                        if self.current_char() == Some('=') {
                            self.advance();
                            Token::EqualEqual
                        } else {
                            Token::Equal
                        }
                    }
                    '!' => {
                        self.advance();
                        if self.current_char() == Some('=') {
                            self.advance();
                            Token::NotEqual
                        } else {
                            Token::Not
                        }
                    }
                    '<' => {
                        self.advance();
                        if self.current_char() == Some('=') {
                            self.advance();
                            Token::LessEqual
                        } else {
                            Token::Less
                        }
                    }
                    '>' => {
                        self.advance();
                        if self.current_char() == Some('=') {
                            self.advance();
                            Token::GreaterEqual
                        } else {
                            Token::Greater
                        }
                    }
                    '&' => {
                        self.advance();
                        Token::And
                    }
                    '^' => {
                        self.advance();
                        Token::Xor
                    }
                    '"' => {
                        self.advance();
                        let mut s = String::new();
                        while let Some(c) = self.current_char() {
                            if c == '"' {
                                self.advance();
                                break;
                            }
                            s.push(c);
                            self.advance();
                        }
                        Token::String(s)
                    }
                    _ => {
                        if ch.is_digit(10) {
                            Token::Number(self.read_number())
                        } else if ch.is_alphabetic() || ch == '_' {
                            let ident = self.read_identifier();
                            match ident.as_str() {
                                "fn" => Token::Fn,
                                "pub" => Token::Pub,
                                "module" => Token::Module,
                                "use" => Token::Use,
                                "type" => Token::Type,
                                "struct" => Token::Struct,
                                "if" => Token::If,
                                "else" => Token::Else,
                                "for" => Token::For,
                                "while" => Token::While,
                                "return" => Token::Return,
                                "let" => Token::Let,
                                "mut" => Token::Mut,
                                "true" => Token::True,
                                "false" => Token::False,
                                _ => Token::Identifier(ident),
                            }
                        } else {
                            self.advance();
                            self.next_token()
                        }
                    }
                }
            }
        }
    }
}

// ============================================================================
// Value - 런타임 값
// ============================================================================

#[derive(Debug, Clone)]
enum Value {
    Integer(i64),
    Boolean(bool),
    String(String),
    Array(Vec<Value>),
    Null,
}

impl Value {
    fn to_string(&self) -> String {
        match self {
            Value::Integer(n) => n.to_string(),
            Value::Boolean(b) => b.to_string(),
            Value::String(s) => s.clone(),
            Value::Array(_) => "[array]".to_string(),
            Value::Null => "null".to_string(),
        }
    }
}

// ============================================================================
// VM - 가상 머신
// ============================================================================

struct VM {
    variables: HashMap<String, Value>,
    functions: HashMap<String, Vec<Token>>,
}

impl VM {
    fn new() -> Self {
        VM {
            variables: HashMap::new(),
            functions: HashMap::new(),
        }
    }

    fn set_variable(&mut self, name: String, value: Value) {
        self.variables.insert(name, value);
    }

    fn get_variable(&self, name: &str) -> Option<Value> {
        self.variables.get(name).cloned()
    }

    fn eval_expression(&self, tokens: &[Token]) -> Value {
        if tokens.is_empty() {
            return Value::Null;
        }

        match &tokens[0] {
            Token::Number(n) => Value::Integer(*n),
            Token::String(s) => Value::String(s.clone()),
            Token::True => Value::Boolean(true),
            Token::False => Value::Boolean(false),
            Token::Identifier(name) => self.get_variable(name).unwrap_or(Value::Null),
            _ => Value::Null,
        }
    }
}

