fn main() {
    let args: Vec<String> = std::env::args().collect();

    // Parse CLI arguments with improved error handling
    match args.get(1).map(|s| s.as_str()) {
        Some("--compile-aot") => {
            // Phase 10: Self-Compilation Verification
            compile_aot_mode(&args[2..]);
        }
        Some("--bench") => {
            run_benchmarks();
        }
        Some("--test") => {
            run_integration_tests();
        }
        Some(arg) if arg.ends_with(".fl") => {
            // Execute .fl file
            if !Path::new(arg).exists() {
                eprintln!("Error: failed to read '{}': file not found", arg);
                std::process::exit(1);
            }
            execute_file(arg);
        }
        Some("--help") | Some("-h") => {
            print_help();
        }
        Some(arg) if arg.starts_with("--") => {
            // Unknown flag
            eprintln!("Error: unknown option '{}'\nRun 'freelang --help' for usage.", arg);
            std::process::exit(1);
        }
        Some(arg) => {
            eprintln!("Error: unknown argument '{}'\nRun 'freelang --help' for usage.", arg);
            std::process::exit(1);
        }
        None => {
            // Default: run Challenge 14 validator + REPL
            run_default_mode();
        }
    }
}

