fn load_aot_compiler() -> Result<String, String> {
    // Phase 10 Stage 2: Load AOT Compiler from freelang-aot-compiler
    // Discovers and loads all .fl files from ../freelang-aot-compiler/src/

    let aot_path = "../freelang-aot-compiler/src";

    // Define all 41 FreeLang files in dependency order
    let files = vec![
        // Core language structures
        "token.fl",
        "ast.fl",

        // Lexical analysis
        "lexer.fl",

        // Syntactic analysis
        "parser.fl",

        // Intermediate representation
        "ir.fl",

        // Code generation
        "codegen.fl",

        // Optimization
        "optimizer.fl",
        "advanced_optimizer.fl",

        // Bootstrap self-hosting
        "bootstrap_stage1.fl",
        "bootstrap_stage2.fl",

        // Type system
        "type_inference.fl",
        "generics.fl",

        // Async/concurrency
        "async_await.fl",
        "concurrency.fl",

        // Standard library
        "string_ops.fl",
        "collections.fl",
        "memory_management.fl",
        "io_operations.fl",

        // Testing framework
        "testing_framework.fl",

        // Build system
        "build_scripts.fl",
        "build_cache.fl",
        "incremental_compilation.fl",

        // Advanced features
        "macros.fl",
        "reflection.fl",
        "compile_time_eval.fl",
        "conditional_compilation.fl",
        "compilation_invariants.fl",

        // Extended bootloader
        "bootloader_extended.fl",

        // Additional modules
        "error_handling.fl",
        "runtime_errors.fl",
        "performance_analysis.fl",
        "debugging_symbols.fl",
        "gc_implementation.fl",
        "constants.fl",
        "prelude.fl",
    ];

    let mut combined = String::new();
    let mut loaded_count = 0;
    let mut total_lines = 0;

    // Add header comment
    combined.push_str("// ============================================================================\n");
    combined.push_str("// FreeLang AOT Compiler - Phase 20-26\n");
    combined.push_str("// Self-Compilation Test Suite (41 modules, ~14,426 lines)\n");
    combined.push_str("// Generated: 2026-03-16 Phase 10 Stage 2\n");
    combined.push_str("// ============================================================================\n\n");

    // Try to load each file
    for filename in files {
        let file_path = format!("{}/{}", aot_path, filename);

        match fs::read_to_string(&file_path) {
            Ok(content) => {
                let line_count = content.lines().count();
                total_lines += line_count;
                loaded_count += 1;

                // Add module separator
                combined.push_str(&format!("\n// ─────────────────────────────────────────────────────────────\n"));
                combined.push_str(&format!("// Module: {} ({} lines)\n", filename, line_count));
                combined.push_str(&format!("// ─────────────────────────────────────────────────────────────\n\n"));

                // Add file content
                combined.push_str(&content);
                combined.push_str("\n");
            }
            Err(e) => {
                // Non-critical: file not found, continue with next
                let placeholder = format!(
                    "// ⚠️  Module not found: {} (skipped: {})\n",
                    filename, e
                );
                combined.push_str(&placeholder);
            }
        }
    }

    // Add footer with statistics
    combined.push_str("\n// ============================================================================\n");
    combined.push_str(&format!("// Statistics: {} / {} files loaded, {} total lines\n",
        loaded_count, files.len(), total_lines));
    combined.push_str("// Status: PHASE 10 STAGE 2 - AOT SELF-COMPILATION TEST\n");
    combined.push_str("// ============================================================================\n");

    if loaded_count == 0 {
        return Err("No AOT files found. Is freelang-aot-compiler/src present?".to_string());
    }

    println!("   Discovered {} FreeLang modules ({} lines total)", loaded_count, total_lines);

    Ok(combined)
}

