fn interactive_mode() {
    let mut vm = VM::new();

    println!("\n╭─ Interactive FreeLang Console ────────────────────────╮");
    println!("│ Type commands: set <var> <value>, get <var>, test  │");
    println!("│ Type 'exit' to quit                                │");
    println!("╰───────────────────────────────────────────────────────╯\n");

    loop {
        print!("fl> ");
        // Safely flush stdout - if it fails, continue
        let _ = io::stdout().flush();

        let mut input = String::new();
        // Safely read stdin - if it fails, exit gracefully
        match io::stdin().read_line(&mut input) {
            Ok(0) => {
                // EOF reached
                println!("\nGoodbye!");
                break;
            }
            Err(_) => {
                // Read error - exit gracefully
                eprintln!("Error reading input");
                break;
            }
            Ok(_) => {}  // Successfully read line
        }

        let input = input.trim();
        if input == "exit" {
            println!("Goodbye!");
            break;
        }

        let parts: Vec<&str> = input.split_whitespace().collect();
        match parts.as_slice() {
            ["set", var, value] => {
                if let Ok(n) = value.parse::<i64>() {
                    vm.set_variable(var.to_string(), Value::Integer(n));
                    println!("Set {} = {}", var, n);
                } else {
                    vm.set_variable(var.to_string(), Value::String(value.to_string()));
                    println!("Set {} = \"{}\"", var, value);
                }
            }
            ["get", var] => {
