// Phase 10 Stage 4: Integration Pipeline Tests
// Full Lexer → Parser → Executor flow validation

#[cfg(test)]
mod pipeline_tests {
    use std::collections::HashMap;

    // Mock structures (in real project, import from main lib)
    #[derive(Debug, Clone, PartialEq)]
    enum Token {
        Fn,
        Identifier(String),
        LeftParen,
        RightParen,
        LeftBrace,
        RightBrace,
        Return,
        Number(i64),
        Plus,
        Semicolon,
        Colon,
        Arrow,
        I32,
        Eof,
    }

    struct Lexer {
        input: Vec<char>,
        pos: usize,
    }

    impl Lexer {
        fn new(input: &str) -> Self {
            Lexer {
                input: input.chars().collect(),
                pos: 0,
            }
        }

        fn tokenize(&mut self) -> Result<Vec<Token>, String> {
            let mut tokens = Vec::new();

            while self.pos < self.input.len() {
                match self.current_char() {
                    None => break,
                    Some(ch) if ch.is_whitespace() => {
                        self.pos += 1;
                    }
                    Some('(') => {
                        tokens.push(Token::LeftParen);
                        self.pos += 1;
                    }
                    Some(')') => {
                        tokens.push(Token::RightParen);
                        self.pos += 1;
                    }
                    Some('{') => {
                        tokens.push(Token::LeftBrace);
                        self.pos += 1;
                    }
                    Some('}') => {
                        tokens.push(Token::RightBrace);
                        self.pos += 1;
                    }
                    Some('+') => {
                        tokens.push(Token::Plus);
                        self.pos += 1;
                    }
                    Some(':') => {
                        tokens.push(Token::Colon);
                        self.pos += 1;
                    }
                    Some(';') => {
                        tokens.push(Token::Semicolon);
                        self.pos += 1;
                    }
                    Some(ch) if ch.is_digit(10) => {
                        let num = self.read_number();
                        tokens.push(Token::Number(num));
                    }
                    Some(ch) if ch.is_alphabetic() || ch == '_' => {
                        let ident = self.read_identifier();
                        let tok = match ident.as_str() {
                            "fn" => Token::Fn,
                            "return" => Token::Return,
                            "i32" => Token::I32,
                            _ => Token::Identifier(ident),
                        };
                        tokens.push(tok);
                    }
                    Some(ch) => {
                        return Err(format!("Unknown character: {}", ch));
                    }
                }
            }

            tokens.push(Token::Eof);
            Ok(tokens)
        }

        fn current_char(&self) -> Option<char> {
            if self.pos < self.input.len() {
                Some(self.input[self.pos])
            } else {
                None
            }
        }

        fn read_identifier(&mut self) -> String {
            let mut result = String::new();
            while let Some(ch) = self.current_char() {
                if ch.is_alphanumeric() || ch == '_' {
                    result.push(ch);
                    self.pos += 1;
                } else {
                    break;
                }
            }
            result
        }

        fn read_number(&mut self) -> i64 {
            let mut result = 0i64;
            while let Some(ch) = self.current_char() {
                if ch.is_digit(10) {
                    result = result * 10 + (ch as i64 - '0' as i64);
                    self.pos += 1;
                } else {
                    break;
                }
            }
            result
        }
    }

    // Simple AST
    #[derive(Debug)]
    struct Function {
        name: String,
        params: Vec<(String, String)>, // (name, type)
        return_type: String,
        body: Vec<Statement>,
    }

    #[derive(Debug)]
    enum Statement {
        Return(Expression),
    }

    #[derive(Debug)]
    enum Expression {
        Number(i64),
        Add(Box<Expression>, Box<Expression>),
        Call(String, Vec<Expression>),
    }

    struct Parser {
        tokens: Vec<Token>,
        pos: usize,
    }

    impl Parser {
        fn new(tokens: Vec<Token>) -> Self {
            Parser { tokens, pos: 0 }
        }

        fn parse(&mut self) -> Result<Vec<Function>, String> {
            let mut functions = Vec::new();

            while self.current() != &Token::Eof {
                functions.push(self.parse_function()?);
            }

            Ok(functions)
        }

        fn parse_function(&mut self) -> Result<Function, String> {
            self.expect(&Token::Fn)?;

            let name = self.parse_identifier()?;
            self.expect(&Token::LeftParen)?;

            let params = self.parse_params()?;

            self.expect(&Token::RightParen)?;
            self.expect(&Token::Colon)?;

            let return_type = self.parse_identifier()?;

            self.expect(&Token::LeftBrace)?;

            let mut body = Vec::new();
            while self.current() != &Token::RightBrace {
                body.push(self.parse_statement()?);
            }

            self.expect(&Token::RightBrace)?;

            Ok(Function {
                name,
                params,
                return_type,
                body,
            })
        }

        fn parse_params(&mut self) -> Result<Vec<(String, String)>, String> {
            let mut params = Vec::new();

            while self.current() != &Token::RightParen {
                let param_name = self.parse_identifier()?;
                self.expect(&Token::Colon)?;
                let param_type = self.parse_identifier()?;

                params.push((param_name, param_type));

                if self.current() != &Token::RightParen {
                    // Assume comma separated (simplified)
                    self.pos += 1;
                }
            }

            Ok(params)
        }

        fn parse_statement(&mut self) -> Result<Statement, String> {
            self.expect(&Token::Return)?;
            let expr = self.parse_expression()?;
            self.expect(&Token::Semicolon)?;
            Ok(Statement::Return(expr))
        }

        fn parse_expression(&mut self) -> Result<Expression, String> {
            let mut expr = self.parse_primary()?;

            while self.current() == &Token::Plus {
                self.pos += 1;
                let right = self.parse_primary()?;
                expr = Expression::Add(Box::new(expr), Box::new(right));
            }

            Ok(expr)
        }

        fn parse_primary(&mut self) -> Result<Expression, String> {
            match self.current() {
                Token::Number(n) => {
                    let val = *n;
                    self.pos += 1;
                    Ok(Expression::Number(val))
                }
                Token::Identifier(name) => {
                    let func_name = name.clone();
                    self.pos += 1;

                    if self.current() == &Token::LeftParen {
                        self.pos += 1;
                        let mut args = Vec::new();

                        while self.current() != &Token::RightParen {
                            args.push(self.parse_expression()?);
                            if self.current() != &Token::RightParen {
                                self.pos += 1; // comma
                            }
                        }

                        self.expect(&Token::RightParen)?;
                        Ok(Expression::Call(func_name, args))
                    } else {
                        Ok(Expression::Number(0)) // Simplified
                    }
                }
                _ => Err(format!("Unexpected token: {:?}", self.current())),
            }
        }

        fn parse_identifier(&mut self) -> Result<String, String> {
            match self.current() {
                Token::Identifier(name) => {
                    let result = name.clone();
                    self.pos += 1;
                    Ok(result)
                }
                Token::I32 => {
                    self.pos += 1;
                    Ok("i32".to_string())
                }
                _ => Err(format!("Expected identifier, got {:?}", self.current())),
            }
        }

        fn expect(&mut self, expected: &Token) -> Result<(), String> {
            if std::mem::discriminant(self.current()) == std::mem::discriminant(expected) {
                self.pos += 1;
                Ok(())
            } else {
                Err(format!("Expected {:?}, got {:?}", expected, self.current()))
            }
        }

        fn current(&self) -> &Token {
            self.tokens.get(self.pos).unwrap_or(&Token::Eof)
        }
    }

    // Simple Executor
    struct Executor {
        variables: HashMap<String, i64>,
    }

    impl Executor {
        fn new() -> Self {
            Executor {
                variables: HashMap::new(),
            }
        }

        fn execute_functions(&mut self, functions: &[Function]) -> Result<i64, String> {
            // Execute main function if exists
            for func in functions {
                if func.name == "main" {
                    return self.execute_function(func);
                }
            }
            Ok(0)
        }

        fn execute_function(&mut self, func: &Function) -> Result<i64, String> {
            for stmt in &func.body {
                match stmt {
                    Statement::Return(expr) => {
                        return self.eval_expression(expr);
                    }
                }
            }
            Ok(0)
        }

        fn eval_expression(&self, expr: &Expression) -> Result<i64, String> {
            match expr {
                Expression::Number(n) => Ok(*n),
                Expression::Add(left, right) => {
                    let l = self.eval_expression(left)?;
                    let r = self.eval_expression(right)?;
                    Ok(l + r)
                }
                Expression::Call(func_name, _args) => {
                    Err(format!("Function call not implemented: {}", func_name))
                }
            }
        }
    }

    // ========================================================================
    // TESTS
    // ========================================================================

    #[test]
    fn test_full_pipeline_simple_addition() {
        let source = r#"
fn add(a: i32, b: i32): i32 {
    return a + b;
}

fn main(): i32 {
    return 19 + 23;
}
        "#;

        // Step 1: Tokenization
        let mut lexer = Lexer::new(source);
        let tokens = lexer.tokenize().expect("Tokenization failed");

        println!("✅ Tokenization: {} tokens", tokens.len());
        assert!(tokens.len() > 20, "Too few tokens: {}", tokens.len());

        // Step 2: Parsing
        let mut parser = Parser::new(tokens);
        let functions = parser.parse().expect("Parsing failed");

        println!("✅ Parsing: {} functions", functions.len());
        assert_eq!(functions.len(), 2, "Expected 2 functions");
        assert_eq!(functions[0].name, "add");
        assert_eq!(functions[1].name, "main");

        // Step 3: Execution
        let mut executor = Executor::new();
        let result = executor.execute_functions(&functions).expect("Execution failed");

        println!("✅ Execution: result = {}", result);
        assert_eq!(result, 42, "Expected 42, got {}", result);
    }

    #[test]
    fn test_tokenization_count() {
        let source = "fn fib(n: i32): i32 { return 1 + 1; }";

        let mut lexer = Lexer::new(source);
        let tokens = lexer.tokenize().expect("Tokenization failed");

        println!("Source length: {} chars", source.len());
        println!("Token count: {}", tokens.len());

        let throughput = tokens.len() as f64 / source.len() as f64;
        println!("Throughput: {:.2} tokens/char", throughput);

        assert!(tokens.len() > 10);
    }

    #[test]
    fn test_error_handling_unterminated_string() {
        // This would fail in a real string lexer
        // For now, just test basic error scenarios

        let invalid_codes = vec![
            "fn broken( { return 1; }",  // mismatched parens
            "fn test: { }",              // missing identifier
        ];

        for code in invalid_codes {
            let mut lexer = Lexer::new(code);
            let result = lexer.tokenize();

            // At least it should produce tokens without panicking
            assert!(result.is_ok() || result.is_err());
        }
    }

    #[test]
    fn test_multiple_functions_parsing() {
        let source = r#"
fn add(x: i32, y: i32): i32 {
    return x + y;
}

fn sub(x: i32, y: i32): i32 {
    return x + y;
}

fn main(): i32 {
    return 10 + 5;
}
        "#;

        let mut lexer = Lexer::new(source);
        let tokens = lexer.tokenize().expect("Tokenization failed");

        let mut parser = Parser::new(tokens);
        let functions = parser.parse().expect("Parsing failed");

        assert_eq!(functions.len(), 3);
        assert_eq!(functions[0].name, "add");
        assert_eq!(functions[1].name, "sub");
        assert_eq!(functions[2].name, "main");

        println!("✅ Parsed {} functions successfully", functions.len());
    }
}

