// Phase 10 Stage 4: Fibonacci Example Test
// Tests the fib.fl example through the full pipeline

#[cfg(test)]
mod fib_tests {
    use std::collections::HashMap;

    // Simplified Fibonacci Calculator
    // This simulates what happens when fib.fl is compiled and executed

    fn fib_recursive(n: i32) -> i32 {
        if n <= 1 {
            return n;
        }
        fib_recursive(n - 1) + fib_recursive(n - 2)
    }

    fn fib_iterative(n: i32) -> i32 {
        if n <= 1 {
            return n;
        }

        let mut a = 0;
        let mut b = 1;

        for _ in 2..=n {
            let temp = a + b;
            a = b;
            b = temp;
        }

        b
    }

    // Test metrics
    struct TestMetrics {
        name: String,
        iterations: usize,
        total_time_ms: f64,
        avg_time_us: f64,
    }

    impl TestMetrics {
        fn print(&self) {
            println!(
                "  {} ({}x): {:.2}ms total, {:.2}µs avg",
                self.name, self.iterations, self.total_time_ms, self.avg_time_us
            );
        }
    }

    // ========================================================================
    // TESTS
    // ========================================================================

    #[test]
    fn test_fib_recursive_correctness() {
        let test_cases = vec![
            (0, 0),
            (1, 1),
            (2, 1),
            (3, 2),
            (4, 3),
            (5, 5),
            (6, 8),
            (7, 13),
            (8, 21),
            (9, 34),
            (10, 55),
        ];

        println!("Testing Recursive Fibonacci:");
        for (n, expected) in test_cases {
            let result = fib_recursive(n);
            assert_eq!(result, expected, "fib({}) = {}, expected {}", n, result, expected);
            println!("  ✅ fib({}) = {}", n, result);
        }
    }

    #[test]
    fn test_fib_iterative_correctness() {
        let test_cases = vec![
            (0, 0),
            (1, 1),
            (2, 1),
            (3, 2),
            (4, 3),
            (5, 5),
            (6, 8),
            (7, 13),
            (8, 21),
            (9, 34),
            (10, 55),
        ];

        println!("Testing Iterative Fibonacci:");
        for (n, expected) in test_cases {
            let result = fib_iterative(n);
            assert_eq!(result, expected, "fib({}) = {}, expected {}", n, result, expected);
            println!("  ✅ fib({}) = {}", n, result);
        }
    }

    #[test]
    fn test_fib_equivalence() {
        // Verify recursive and iterative give same results
        println!("Testing Recursive vs Iterative Equivalence:");
        for n in 0..=15 {
            let rec = fib_recursive(n);
            let iter = fib_iterative(n);
            assert_eq!(
                rec, iter,
                "Mismatch at n={}: recursive={}, iterative={}",
                n, rec, iter
            );
            println!("  ✅ fib({}) = {} (both match)", n, rec);
        }
    }

    #[test]
    fn test_fib_performance_recursive() {
        let start = std::time::Instant::now();

        // Calculate fib(10) 1000 times
        let mut sum = 0i64;
        for _ in 0..1000 {
            sum += fib_recursive(10) as i64;
        }

        let elapsed = start.elapsed();

        let metrics = TestMetrics {
            name: "Recursive fib(10)".to_string(),
            iterations: 1000,
            total_time_ms: elapsed.as_millis() as f64,
            avg_time_us: elapsed.as_micros() as f64 / 1000.0,
        };

        metrics.print();

        // Each fib(10) should be 55
        assert_eq!(sum, 55000, "Sum check failed");

        // Performance assertion: should be fast enough
        assert!(
            elapsed.as_millis() < 500,
            "Recursive fib too slow: {}ms",
            elapsed.as_millis()
        );
    }

    #[test]
    fn test_fib_performance_iterative() {
        let start = std::time::Instant::now();

        // Calculate fib(10) 10000 times (iterative is faster)
        let mut sum = 0i64;
        for _ in 0..10000 {
            sum += fib_iterative(10) as i64;
        }

        let elapsed = start.elapsed();

        let metrics = TestMetrics {
            name: "Iterative fib(10)".to_string(),
            iterations: 10000,
            total_time_ms: elapsed.as_millis() as f64,
            avg_time_us: elapsed.as_micros() as f64 / 10000.0,
        };

        metrics.print();

        // Each fib(10) should be 55
        assert_eq!(sum, 550000, "Sum check failed");

        // Performance assertion: should be very fast
        assert!(
            elapsed.as_millis() < 50,
            "Iterative fib too slow: {}ms",
            elapsed.as_millis()
        );
    }

    #[test]
    fn test_fib_larger_values() {
        println!("Testing larger Fibonacci values:");

        let large_cases = vec![
            (20, 6765),
            (25, 75025),
        ];

        for (n, expected) in large_cases {
            let result = fib_iterative(n); // Use iterative for larger values
            assert_eq!(result, expected, "fib({}) = {}, expected {}", n, result, expected);
            println!("  ✅ fib({}) = {}", n, result);
        }
    }

    #[test]
    fn test_fib_edge_cases() {
        println!("Testing edge cases:");

        // Negative numbers (implementation dependent, but typically return as-is)
        assert_eq!(fib_iterative(0), 0);
        assert_eq!(fib_iterative(1), 1);

        println!("  ✅ Edge cases pass");
    }

    #[test]
    fn test_fib_sequence_generation() {
        // Generate first 20 Fibonacci numbers
        let mut sequence = Vec::new();
        for i in 0..20 {
            sequence.push(fib_iterative(i));
        }

        println!("First 20 Fibonacci numbers:");
        println!("{:?}", sequence);

        // Verify sequence properties
        for i in 2..sequence.len() {
            assert_eq!(
                sequence[i], sequence[i - 1] + sequence[i - 2],
                "Fib sequence property violated at index {}",
                i
            );
        }

        println!("  ✅ Sequence property verified");
    }

    #[test]
    fn test_fib_performance_comparison() {
        println!("\n=== Fibonacci Performance Comparison ===");

        // Test with n=20
        let n = 20;

        // Recursive
        let start = std::time::Instant::now();
        let rec = fib_recursive(n);
        let rec_time = start.elapsed();

        // Iterative
        let start = std::time::Instant::now();
        let iter = fib_iterative(n);
        let iter_time = start.elapsed();

        println!("fib({}) = {}", n, rec);
        println!("  Recursive: {:.2}ms", rec_time.as_millis());
        println!("  Iterative: {:.2}µs", iter_time.as_micros());

        let speedup = rec_time.as_micros() as f64 / iter_time.as_micros() as f64;
        println!("  Speedup: {:.0}x faster (iterative)", speedup);

        assert_eq!(rec, iter);
        assert!(iter_time < rec_time, "Iterative should be faster");
    }
}

